package com.nbi.account.model;

import java.math.BigDecimal;

// A resource: a meaningful banking "thing" with a stable identity.
public class Account {
    private String accountId;      // e.g. SAV2001
    private String holderName;     // Rajesh Kumar
    private BigDecimal balance;    // money ALWAYS BigDecimal

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    public void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}
```

