package com.nbi.account.service;

import com.nbi.account.model.Account;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class AccountService {
    // In-memory store standing in for a real repository.
    private final Map<String, Account> store = new HashMap<>();

    public AccountService() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00")));
    }

    public Optional<Account> findById(String id) {
        return Optional.ofNullable(store.get(id));
    }

    // Creating a transfer resource: stateless, everything needed is in the request.
    public String transfer(String from, String to, BigDecimal amount) {
        Account src = store.get(from);
        Account dst = store.get(to);
        src.debit(amount);
        dst.credit(amount);
        return "TXF-" + UUID.randomUUID().toString().substring(0, 8);
    }
}
```

