// ─── File: src/main/java/com/nbi/account/controller/AccountController.java ───
package com.nbi.account.controller;

import com.nbi.account.dto.*;
import com.nbi.account.model.Account;
import com.nbi.account.service.AccountService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;

@RestController
@RequestMapping("/api/v1")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    // RESTful READ: noun in URL, GET verb. Cache header makes it cacheable.
    @GetMapping("/accounts/{id}")
    public ResponseEntity<AccountResponse> getAccount(@PathVariable String id) {
        return service.findById(id)
            .map(a -> ResponseEntity.ok()
                .cacheControl(org.springframework.http.CacheControl.maxAge(
                        java.time.Duration.ofSeconds(30)))
                .body(new AccountResponse(a.getAccountId(), a.getHolderName(), a.getBalance())))
            .orElse(ResponseEntity.notFound().build());
    }

    // RESTful CREATE: POST to a collection noun, returns 201 + Location header.
    @PostMapping("/transfers")
    public ResponseEntity<String> createTransfer(@Valid @RequestBody TransferRequest req) {
        String txId = service.transfer(req.from(), req.to(), req.amount());
        return ResponseEntity.created(URI.create("/api/v1/transfers/" + txId)).body(txId);
    }
}
```
